ret_t validate_credentials_ldap(cherokee_validator_ldap_t *ldap, cherokee_connection_t *conn) {
    if (!ldap || !conn) {
        return ret_error;
    }

    if (!conn->username || !conn->password) {
        return ret_error;
    }

    if (strlen(conn->username) == 0 || strlen(conn->password) == 0) {
        return ret_error;
    }

    if (!ldap->base_dn || !ldap->search_filter) {
        return ret_error;
    }

    char filter[256];
    int filter_len = snprintf(filter, sizeof(filter), ldap->search_filter, conn->username);
    if (filter_len < 0 || filter_len >= sizeof(filter)) {
        return ret_error;
    }

    LDAPMessage *result = NULL;
    int ldap_result = ldap_search_ext_s(ldap->handle, ldap->base_dn, LDAP_SCOPE_SUBTREE, filter, NULL, 0, NULL, NULL, LDAP_NO_LIMIT, LDAP_NO_LIMIT, &result);
    if (ldap_result != LDAP_SUCCESS) {
        ldap_msgfree(result);
        return ret_error;
    }

    int count = ldap_count_entries(ldap->handle, result);
    if (count != 1) {
        ldap_msgfree(result);
        return (count == 0) ? ret_not_found : ret_error;
    }

    LDAPMessage *entry = ldap_first_entry(ldap->handle, result);
    if (!entry) {
        ldap_msgfree(result);
        return ret_error;
    }

    char *dn = ldap_get_dn(ldap->handle, entry);
    if (!dn) {
        ldap_msgfree(result);
        return ret_error;
    }

    int bind_result = ldap_bind_s(ldap->handle, dn, conn->password, LDAP_AUTH_SIMPLE);
    if (bind_result != LDAP_SUCCESS) {
        ldap_memfree(dn);
        ldap_msgfree(result);
        return ret_error;
    }

    ldap_memfree(dn);
    ldap_msgfree(result);
    return ret_ok;
}
